'use strict';
const styles={editorial:{name:'白昼编辑室',en:'THE OBSERVATION DESK',desc:'把脉络展开，把判断留给证据。'},transit:{name:'轨道信号站',en:'SIGNAL TRANSIT',desc:'沿平台轨道，追踪同一议题的不同切面。'},console:{name:'夜航控制台',en:'NIGHTWATCH / RESEARCH TERMINAL',desc:'逐条检索，逐项核验。'},atlas:{name:'纸片研究所',en:'FIELD NOTES ATLAS',desc:'把观点放在一起，把差异看得更近。'}};
const platforms={bilibili:{name:'Bilibili',short:'B站',code:'BL',color:'#62a8b9',note:'官方综合榜保存前10项及两条显式AI标签作品；同时保留创作流程的索引与二手线索。'},xiaohongshu:{name:'小红书',short:'小红书',code:'RED',color:'#d57575',note:'工具的日常使用成本与可信度；已查笔记显示暂时无法浏览，以二手线索为主，不据此断言已删除。'},weibo:{name:'微博',short:'微博',code:'WB',color:'#ce943a',note:'科技分类官方榜选取范围单独标明，另有职业转型与AI面试讨论；分类名次不等于综合榜。'},douyin:{name:'抖音',short:'抖音',code:'DY',color:'#766ec0',note:'官方热榜时间与保存范围单独标明，另有创作及历史访谈线索；热度不是人数。'},x:{name:'X',short:'X',code:'X',color:'#5b8390',note:'已直读1条主帖和2条回复，其余保留各自来源等级；回复样本不具代表性。'},wechat:{name:'微信公众号',short:'公众号',code:'WX',color:'#689d76',note:'长文论证与业务应用；通过署名转载读取，未直接读取公众号原文。'}};
const sourceNames={official_rank:'官方榜单快照',secondary_report:'二手报道',search_snippet:'搜索索引',primary_post:'直接原文'};
const style=document.body.dataset.style,platform=document.body.dataset.platform,config=styles[style],isSummary=platform==='summary';
const qs=new URLSearchParams(location.search);let metadata={},temporal={batches:[]},data=[],selected=new Set(),filtered=[],groups=[];
let state={q:qs.get('q')||'',domain:qs.get('domain')||'all',source:qs.get('source')||'all',time:qs.get('time')||'all'};
const e=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const date=r=>r.published_at?String(r.published_at).slice(0,10):'日期未核验';
const old=r=>!!r.published_at&&String(r.published_at).slice(0,10)<metadata.recent_content_start;
function checkedLabel(value=metadata.last_checked_at){if(!value)return '未标明';const dt=new Date(value);if(Number.isNaN(dt.getTime()))return value;return new Intl.DateTimeFormat('zh-CN',{timeZone:metadata.display_timezone||'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false}).format(dt)+'（UTC+8）';}
function contentRange(){const r=metadata.known_content_date_range||{};return r.earliest&&r.latest?r.earliest+' 至 '+r.latest+'（已知日期）':'各条材料分别标注';}
const displayAuthor=r=>r.account_name||r.author_name||r.author||'发布者未核验';
const sourceURL=r=>r.source_type==='primary_post'?r.url:r.evidence_url||r.secondary_source_url||r.source_url||r.url;
const tags=r=>`<span class="badge platform-badge">${platforms[r.platform]?.short||e(r.platform)}</span><span class="badge ${r.source_type}">${sourceNames[r.source_type]||e(r.source_type)}</span>${r.background?'<span class="badge warn">官网背景 · 非X帖</span>':r.excluded_from_metrics?'<span class="badge warn">弱线索 · 不计覆盖</span>':old(r)?'<span class="badge warn">历史材料</span>':''}`;
const counts=rs=>Object.keys(platforms).map(p=>({p,n:rs.filter(r=>r.platform===p&&!r.excluded_from_metrics).length}));
function route(p,s=style){return `/${s}/${p}/`;}
function shell(){let nav=Object.entries(platforms).map(([p,v])=>`<a href="${route(p)}" ${p===platform?'aria-current="page"':''}><i style="--p:${v.color}">${v.code}</i><span>${v.name}</span></a>`).join('');document.getElementById('app').innerHTML=`<header class="topbar"><a class="brand" href="/"><img src="/favicon.svg" alt="">澄镜 <span>${config.en}</span></a><div class="top-tools"><span class="stamp" title="最新证据采集时间，不代表所有平台同时更新">最近核查 ${e(checkedLabel())}</span><label class="style-switch"><span class="sr">切换工作台</span><select id="style-select">${Object.entries(styles).map(([k,v])=>`<option value="${k}" ${k===style?'selected':''}>${v.name}</option>`).join('')}</select></label><a class="hub-link" href="/">视图总览 ↗</a></div></header><div class="workspace"><nav class="platform-nav" aria-label="平台导航"><a class="summary-link" href="${route('summary')}" ${isSummary?'aria-current="page"':''}><i>◎</i><span>跨平台综述</span></a>${nav}<div class="nav-bottom">PUBLIC EVIDENCE<br>有出处，才有讨论。</div></nav><main id="main"><section class="page-heading"><div><p class="eyebrow">${isSummary?'CROSS-PLATFORM / OVERVIEW':`${platforms[platform].code} / PLATFORM FIELD NOTES`}</p><h1>${isSummary?'同一个世界，不同的讨论切面':platforms[platform].name+' 观察页'}</h1><p>${isSummary?config.desc:platforms[platform].note}</p></div><span class="page-mark">${isSummary?'06':platforms[platform].code}<small>${isSummary?'PLATFORMS':'SOURCE'}</small></span></section><div class="boundary"><span class="boundary-icon">ⓘ</span><p><strong>初始公开样本 + 三平台后续榜单观察。</strong> 另三个平台官方榜未核验。索引、转载、原始材料分开标记；条目数只表示覆盖，热度值不等于人数。无可审计分母，不显示观点占比。</p><button data-action="method">方法与缺口 ↗</button></div><form class="filters" id="filters"><label class="search"><span>⌕</span><input id="search" type="search" placeholder="检索议题、作者或观点…" aria-label="关键词" value="${e(state.q)}"><kbd>/</kbd></label><label><span class="sr">领域</span><select id="domain"><option value="all">所有领域</option><option value="AI">AI 与技术应用</option><option value="other">其他公共讨论</option><optgroup label="细分领域">${[...new Set(data.filter(r=>isSummary||r.platform===platform).map(r=>r.domain))].sort().map(domain=>`<option value="domain:${e(domain)}">${e(domain)}</option>`).join('')}</optgroup></select></label><label><span class="sr">证据类型</span><select id="source"><option value="all">所有证据</option><option value="official_rank">官方榜单快照</option><option value="secondary_report">二手报道</option><option value="search_snippet">搜索索引</option><option value="primary_post">直接原文 / 官网背景</option></select></label><label><span class="sr">时间范围</span><select id="time"><option value="all">全部时间（含历史）</option><option value="recent">内容日期 ${e(metadata.recent_content_start)} 起</option><option value="unknown">日期未核验</option></select></label><button type="button" data-action="reset" class="text-button">重置</button><div class="export-tools"><button type="button" data-export="json">样本 JSON ↓</button><button type="button" data-export="csv">样本 CSV ↓</button></div></form><div class="result-line"><span id="result-count" aria-live="polite"></span><span class="muted">证据编号是索引，不是排名</span></div><div id="content"></div><footer class="workspace-footer"><span>澄镜 / ${config.name}</span><span>材料日期 ${e(contentRange())} · 静态快照，无自动更新</span><button data-action="method">采样说明</button></footer></main></div><div id="selection-bar" class="selection-bar" hidden><span id="selected-count"></span><button data-action="compare">并排比较 →</button><button data-action="clear" aria-label="清空比较">清空</button></div>`;for(const k of ['domain','source','time'])document.getElementById(k).value=state[k];
 document.getElementById('style-select').onchange=ev=>location.href=route(platform,ev.target.value)+location.search;
 document.getElementById('filters').onsubmit=ev=>ev.preventDefault();document.getElementById('search').oninput=ev=>{state.q=ev.target.value;render();};for(const k of ['domain','source','time'])document.getElementById(k).onchange=ev=>{state[k]=ev.target.value;render();};}
function applies(r){return (isSummary||r.platform===platform)&&(!state.q||[r.title,r.topic,r.claim,r.stance_summary,displayAuthor(r),r.id].join(' ').toLowerCase().includes(state.q.toLowerCase()))&&(state.domain==='all'||(state.domain==='AI'?(r.domain||'').includes('AI'):state.domain==='other'?!(r.domain||'').includes('AI'):state.domain==='domain:'+r.domain))&&(state.source==='all'||r.source_type===state.source)&&(state.time==='all'||(state.time==='unknown'?!r.published_at:!!r.published_at&&date(r)>=metadata.recent_content_start));}
function record(r,index=0){return `<article class="record ${r.background?'background-record':''}" data-id="${r.id}"><div class="record-kicker"><span>${e(r.id)} / ${e(r.domain)}</span><label class="compare-check"><input type="checkbox" data-select="${r.id}" ${selected.has(r.id)?'checked':''} aria-label="比较 ${e(r.title)}"><span>比较</span></label></div><div class="record-badges">${tags(r)}</div><h3><button data-evidence="${r.id}">${e(r.title)}</button></h3><p class="record-claim">${e(r.claim)}</p><div class="stance"><span>观点线索</span><p>${e(r.stance_summary||'未读取观点语料，仅记录榜单显示。')}</p></div><div class="record-meta"><span>${e(displayAuthor(r))}</span><time>${e(date(r))}</time></div><div class="record-actions"><button data-evidence="${r.id}">查看证据 <span>↗</span></button><a href="${e(sourceURL(r))}" target="_blank" rel="noopener noreferrer">${r.source_type==='secondary_report'?'读二手来源':'打开来源'} ↗</a></div></article>`;}
function rows(rs){return `<div class="table-scroll"><table class="evidence-table"><thead><tr><th>选择</th><th>索引 / 平台</th><th>议题与观点</th><th>证据层级</th><th>发布日</th><th>证据</th></tr></thead><tbody>${rs.map(r=>`<tr><td><input type="checkbox" data-select="${r.id}" ${selected.has(r.id)?'checked':''} aria-label="比较 ${e(r.title)}"></td><td><b>${e(r.id)}</b><small>${platforms[r.platform].name}</small></td><td><button class="table-title" data-evidence="${r.id}">${e(r.title)}</button><p>${e(r.stance_summary||'未读取观点语料，仅记录榜单显示。')}</p></td><td><span class="badge ${r.source_type}">${sourceNames[r.source_type]}</span>${r.background?'<small>非 X 帖 · 背景</small>':old(r)?'<small>历史材料</small>':''}</td><td>${e(date(r))}</td><td><button data-evidence="${r.id}" class="evidence-link" aria-label="打开 ${e(r.title)} 的证据">↗</button></td></tr>`).join('')}</tbody></table></div>`;}
function coverage(rs){return `<section class="coverage-panel"><header class="section-head"><h2>采样覆盖</h2><span>仅计本轮条目</span></header><div class="coverage-bars">${counts(rs).map(({p,n})=>`<a href="${route(p)}"><span>${platforms[p].short}</span><div class="bar-track"><i style="width:${n/Math.max(1,...counts(rs).map(v=>v.n))*100}%;background:${platforms[p].color}"></i></div><b>${n}</b></a>`).join('')}</div><p class="fine">数量反映检索覆盖，不可用来比较平台热度。官网背景与未核验弱线索不计入平台覆盖。</p></section>`;}
function gap(){return `<section class="gap-panel"><span class="eyebrow">WHAT WE DO NOT KNOW</span><h2>留白也是信息</h2><div class="empty-chart"><span>—</span><p>观点占比不可用</p></div><p>未获得完整评论样本与一致分母。当前不生成支持率、反对率或受众画像。</p><dl><div><dt>官方热榜</dt><dd>B站、微博、抖音有快照</dd></div><div><dt>原帖实时互动</dt><dd>多数不可用</dd></div><div><dt>人群比例</dt><dd>无证据</dd></div></dl></section>`;}
function story(g,i){const ids=g.ids||g.evidence_ids||[];const visible=ids.map(id=>filtered.find(r=>r.id===id)).filter(Boolean);if(!visible.length)return '';return `<article class="story"><div class="story-top"><span class="story-number">${String(i+1).padStart(2,'0')}</span><span class="badge">${e(g.kind||'同题对照')}</span><span>${new Set(visible.map(r=>r.platform)).size} 平台 · ${visible.length} 条可见证据</span></div><h2>${e(g.title)}</h2><p class="story-summary">${e(g.summary)}</p><div class="story-voices">${visible.map(r=>`<button data-evidence="${r.id}" class="voice"><span><i style="background:${platforms[r.platform].color}"></i>${platforms[r.platform].short} / ${r.id}</span><p>${e(r.stance_summary||'未读取观点语料，仅记录榜单显示。')}</p><small>${e(date(r))} · ${sourceNames[r.source_type]} ↗</small></button>`).join('')}</div><p class="story-caution">${e(g.caution||'这些是具体作者或标题的表达，不代表整个平台。')}</p><button class="text-button" data-group="${i}">选择这些证据进行比较 →</button></article>`;}
function summary(){const stories=groups.map(story).join('');if(style==='editorial')return `<div class="editorial-layout"><section class="main-stories"><div class="section-head"><h2>议题对照 / THE BRIEF</h2><span>按论证组织，不按热度排序</span></div>${stories||empty()}</section><aside>${coverage(filtered)}${gap()}<div class="margin-note"><b>时间核验</b><p>“两类劳动”至少在 6 月已有同题材材料。10 月出现的是再次传播，不等于首次发言。</p><button data-evidence="WD10">查看历史线索 ↗</button></div></aside></div><section class="all-records"><div class="section-head"><h2>证据档案</h2><span>筛选后的全部条目</span></div><div class="records-grid">${filtered.map(record).join('')}</div></section>`;
if(style==='transit')return `${coverage(filtered)}<section class="platform-lanes">${Object.entries(platforms).map(([p,v])=>{let rs=filtered.filter(r=>r.platform===p);return `<section class="lane" style="--lane:${v.color}"><header><i>${v.code}</i><h2>${v.name}</h2><span>${rs.filter(r=>!r.excluded_from_metrics).length} 条</span><a href="${route(p)}" aria-label="进入${v.name}">↗</a></header><div class="lane-records">${rs.length?rs.map(record).join(''):'<p class="empty-inline">此筛选下没有条目</p>'}</div></section>`}).join('')}</section><div class="section-head"><h2>换乘：同题证据</h2></div><section class="story-grid">${stories}</section>`;
if(style==='console')return `<div class="console-strip"><div><span>VISIBLE RECORDS</span><b>${filtered.length}</b></div><div><span>PLATFORMS OBSERVED</span><b>${new Set(filtered.map(r=>r.platform)).size}/6</b></div><div><span>OPINION SHARE</span><b>N/A</b></div><div><span>OFFICIAL SNAPSHOTS</span><b>3/6</b></div></div><div class="console-layout"><section><div class="section-head"><h2>证据流 / EVIDENCE LOG</h2><span>点选标题展开来源</span></div>${rows(filtered)}</section><aside>${gap()}<section class="console-brief"><h2>同题综述</h2>${groups.map((g,i)=>`<details><summary><b>${String(i+1).padStart(2,'0')}</b> ${e(g.title)}</summary><p>${e(g.summary)}</p><small>${e(g.caution)}</small><button data-group="${i}">比较相关证据 ↗</button></details>`).join('')}</section></aside></div>`;
return `<div class="atlas-overview">${coverage(filtered)}<div class="atlas-note"><p class="eyebrow">INITIAL SAMPLE / ${e(metadata.snapshot_date)}</p><h2>同题不一定对立，<br>差异值得细读。</h2><p>先区分“关注重点不同”和“彼此矛盾”。同一转载链也不是独立验证。</p><span>✧</span></div></div><section class="story-grid">${stories}</section><div class="section-head"><h2>所有证据卡</h2><span>可勾选并排比较</span></div><div class="atlas-records">${filtered.map(record).join('')}</div>`;}
function platformView(){let rs=filtered;const active=rs.filter(r=>!r.excluded_from_metrics);const info=`<section class="platform-brief"><div><span>本页可见样本</span><b>${active.length}<small>条</small></b></div><div><span>有日期的材料</span><b>${active.filter(r=>r.published_at).length}<small>条</small></b></div><div><span>可核验人群占比</span><b>—<small>不可用</small></b></div><p>${platforms[platform].note}</p></section>`;if(!rs.length)return info+empty();if(style==='console')return info+`<div class="console-layout"><section>${rows(rs)}</section><aside>${gap()}</aside></div>`;if(style==='transit'){const categories=[['近期线索',rs.filter(r=>!old(r)&&r.published_at)],['历史参照',rs.filter(old)],['日期待核验',rs.filter(r=>!r.published_at)]];return info+`<div class="time-lanes">${categories.map(([name,records])=>`<section class="lane" style="--lane:${platforms[platform].color}"><header><i>●</i><h2>${name}</h2><span>${records.length} 条</span></header><div class="lane-records">${records.map(record).join('')||'<p class="empty-inline">当前没有可用条目</p>'}</div></section>`).join('')}</div>`;}if(style==='atlas')return info+`<div class="atlas-records">${rs.map(record).join('')}</div>`;return info+`<div class="editorial-layout"><section class="records-grid">${rs.map(record).join('')}</section><aside>${gap()}<section class="margin-note"><b>阅读顺序</b><p>标题是入口。观点摘要注明作者表达；证据抽屉保留原始日期、来源关系、互动口径与缺口。</p></section></aside></div>`;}
function empty(){return '<section class="empty"><span>⌕</span><h2>没有匹配的证据</h2><p>尝试更短的关键词，或放宽时间与证据类型。</p><button data-action="reset">清除筛选</button></section>';}
function roleEvidence(r){if(r.author_profile?.role)return {role:r.author_profile.role,basis:r.author_profile.basis||'记录未单列身份依据'};if(r.author_role)return {role:r.author_role,basis:r.author_role+'；完整上下文见来源'};if(r.platform==='wechat'&&r.account_name&&r.source_relationship)return {role:'署名转载中的公众号发布方',basis:r.source_relationship+'；指内容发布关系，不推定作者职业'};return null;}
function rolePanel(){const known=filtered.map(r=>({r,role:roleEvidence(r)})).filter(v=>v.role);const unknown=filtered.filter(r=>!roleEvidence(r)&&r.source_type!=='official_rank');return `<details class="role-panel" ${!isSummary?'open':''}><summary><div><span class="eyebrow">WHO IS SPEAKING / IN THIS SAMPLE</span><h2>样本发声角色 <small>非全平台受众画像</small></h2></div><span>查看身份依据 ⌄</span></summary><p>只展示公开自述、机构账号类型或当前讨论中的角色。转载标注和二手简介也保留来源等级；不推断年龄、性别、收入或政治倾向。</p><div class="role-grid">${known.map(({r,role})=>`<button class="role-card" data-evidence="${r.id}"><span>${platforms[r.platform].short} / ${e(r.id)} · ${sourceNames[r.source_type]}</span><strong>${e(role.role)}</strong><small>依据：${e(role.basis)}</small><i>查看证据 ↗</i></button>`).join('')}${unknown.length?`<div class="role-card unknown-role"><span>身份依据未获取</span><strong>未知，保留未知</strong><small>其余${unknown.length}条可见讨论线索没有足够的角色依据。标题、用户名、语气都不能替代职业或受众证据。</small></div>`:known.length?'':'<div class="role-card unknown-role"><strong>没有可展示的发声角色</strong><small>榜单条目不是作者或评论者，不能生成角色画像。</small></div>'}</div></details>`;}
function latestTemporal(){return temporal.batches?.[temporal.batches.length-1];}
function relevantComparisons(){return (latestTemporal()?.comparison?.comparisons||[]).filter(c=>isSummary||c.platform===platform);}
function rankMovement(change){if(change.newRank===null)return '本次样本未见';const delta=change.newRank-change.oldRank;return delta===0?'名次持平':delta<0?'↑ '+(-delta)+' 位':'↓ '+delta+' 位';}
function temporalMetricName(name,p){return name==='views_display'?'播放显示值':name==='danmaku_display'?'弹幕显示值':p==='weibo'?'页面相邻数值（口径未独立核实）':'平台热度显示值';}
function deltaLabel(metric){const value=metric.displayNumericDelta;if(value===null||value===undefined||!Number.isFinite(value))return '差值不可用';const rounded=(metric.precision||'').includes('rounded');return (rounded?'≈ ':'')+(value>0?'+':'')+new Intl.NumberFormat('zh-CN',{maximumFractionDigits:2}).format(value);}
function temporalPanel(){const cs=relevantComparisons();if(!cs.length)return '';return `<section class="temporal-panel"><header><div><p class="eyebrow">SECOND OBSERVATION / SAME ITEMS</p><h2>两次观察之间，哪些位置变了？</h2></div><button data-export="temporal">比较 JSON ↓</button></header><p class="temporal-boundary">后续榜单记录独立于下方初始样本筛选，不增加90条记录 / 88条覆盖。浏览器观察时间不等于服务器刷新时间，缓存新鲜度未知。仅比较同一条目、同一指标。</p><div class="temporal-cards">${cs.map(c=>{const ranked=c.changes.filter(x=>x.newRank!==null).sort((a,b)=>Math.abs(b.rankDelta)-Math.abs(a.rankDelta)).slice(0,2);return `<article class="temporal-card"><div class="temporal-title"><b>${platforms[c.platform].name}</b><span>${c.platform==='weibo'?'科技分类榜':'同榜单对照'}</span></div><p class="temporal-times">${e(checkedLabel(c.changes[0].oldCapturedAt))}<br>→ ${e(checkedLabel(c.changes[0].newCapturedAt))}</p>${ranked.map(x=>`<div class="temporal-highlight"><span>${e(x.title)}</span><strong>${x.oldRank} → ${x.newRank} <small>${rankMovement(x)}</small></strong>${x.metrics?.[0]?`<p>${temporalMetricName(x.metrics[0].name,c.platform)}：${e(x.metrics[0].oldDisplay)} → ${e(x.metrics[0].newDisplay)}</p>`:''}</div>`).join('')}<p class="fine">${c.platform==='weibo'?'基线仅保存科技榜30项中的12项，不能穷举新增。':`原Top10中有${c.top10RetainedCount}项仍在本次Top10；区间新出现不等于全平台新趋势。`}</p><button class="text-button" data-temporal="${c.platform}">逐项比较 ${c.changes.length} 条 →</button></article>`}).join('')}</div></section>`;}
function temporalDetail(p){const batch=latestTemporal(),c=batch?.comparison?.comparisons.find(c=>c.platform===p);if(!c)return;const snap=batch.snapshots.find(s=>s.platform===p);showDialog('compare',`<div class="dialog-body"><p class="eyebrow">TEMPORAL COMPARISON / ${platforms[p].code}</p><h2>${platforms[p].name} · 同条目两时点比较</h2><p class="fine">初始 ${e(checkedLabel(c.changes[0].oldCapturedAt))} → 后续 ${e(checkedLabel(c.changes[0].newCapturedAt))}。${p==='weibo'?'范围为科技分类前30，不是综合榜。初始仅保存12项，不能把其余本次条目称为新增。':p==='bilibili'?'范围为初始Top10、两条AI作品及本次Top10；排名综合内容质量与近期数据。':'范围为编号Top10及追踪的原Top10退出项，不含无编号置顶。'}</p><div class="table-scroll"><table class="temporal-table"><thead><tr><th>同一条目</th><th>原 → 后续名次</th><th>同口径显示值</th></tr></thead><tbody>${c.changes.map(x=>`<tr><td><b>${e(x.baselineId)}</b><p>${e(x.title)}</p></td><td><strong>${x.oldRank} → ${x.newRank===null?'未见':x.newRank}</strong><small>${rankMovement(x)}</small></td><td>${x.metrics?.length?x.metrics.map(m=>`<div class="metric-pair"><span>${temporalMetricName(m.name,p)}</span><p>${e(m.oldDisplay)} → ${e(m.newDisplay)}</p><small>显示值差 ${deltaLabel(m)}${(m.precision||'').includes('rounded')?' · 取整值相减，非精确增量':''}</small></div>`).join(''):'— 未获取可比值'}</td></tr>`).join('')}</tbody></table></div>${c.newlyObservedInTop10?.length?`<section><h3>本次Top10区间新出现</h3><p>${c.newlyObservedInTop10.map(e).join('；')}</p><p class="fine">此前可能已在Top10之外；不称为全平台新出现，也不证明内容刚发布。</p></section>`:''}<section class="limit-box"><h3>观察边界</h3><p>这是两次页面观察。平台服务器刷新时刻未提供，不能排除缓存；不是持续监控或精确增长测量。平台显示值不是独立人数或赞同人数，弹幕不是评论。${p==='weibo'?'相邻数字的具体指标口径未独立核实，保留显示值，不额外赋予热度定义。':''}</p><p>初始90条记录及88条覆盖保持原样，后续观察另存；初始材料日期不会被本次核查时间替换。</p></section><a class="primary-button" href="${e(snap.sourceUrl)}" target="_blank" rel="noopener noreferrer">打开同一官方榜单 ↗</a></div>`);}
function exportTemporal(){const batch=latestTemporal();const body={scope:'同条目官方榜单两时点观察，非全平台趋势或代表性调查',initial_snapshot_date:metadata.snapshot_date,last_checked_at:metadata.last_checked_at,boundary:temporal.boundary,comparisons:relevantComparisons(),snapshots:(batch?.snapshots||[]).filter(s=>isSummary||s.platform===platform)};const url=URL.createObjectURL(new Blob([JSON.stringify(body,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=`chengjing-temporal-${metadata.updated_date||metadata.snapshot_date}-${platform}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('已导出独立的两时点比较');}
function officialPanel(){return ['bilibili','weibo','douyin'].map(p=>{const rs=filtered.filter(r=>r.source_type==='official_rank'&&r.platform===p);if(!rs.length)return '';const wb=p==='weibo',bili=p==='bilibili',snap=metadata.official_snapshots?.[p]||{},coverage=snap.coverage||{},saved=snap.saved_records??data.filter(r=>r.source_type==='official_rank'&&r.platform===p).length;const scope=bili?`全站综合榜观察到${e(coverage.observed??'未单列总数')}项；${e(coverage.selection||'有选择采样。')} ${e(coverage.note||'')} 排名按内容质量和近期数据综合展示，并非仅按播放量排序。`:wb?`科技分类榜观察到${e(coverage.observed_category_rows??'未单列总数')}项；${e(coverage.selection||'有选择采样，不能据此推算全榜占比。')}分类名次不是综合榜排名。`:e(coverage.ai_note||'单次快照，只说明本次保存条目，不能推论整个平台。');return `<details class="official-panel" ${!isSummary?'open':''}><summary><div><p class="eyebrow">VERIFIED SNAPSHOT / ${bili?'BILIBILI':wb?'WEIBO TECH':'DOUYIN'}</p><h2>${bili?'B站全站综合榜':wb?'微博科技分类榜':'抖音官方热榜'} · 保存${e(saved)}项</h2></div><span>初始榜单核查 ${e(checkedLabel(snap.captured_at||rs[0].captured_at))} <b>⌄</b></span></summary><p>${scope} ${bili?'播放、弹幕不是评论数或独立观众。':'热度不是播放量、评论量或人数。'}榜单核查时间不是话题首次发布时间；内容日期见各条证据。当前筛选可见${rs.length}条。</p><div class="official-ranks">${rs.map(r=>`<button data-evidence="${r.id}"><b>${r.observed_metrics.rank??r.observed_metrics.category_rank}</b><span>${e(r.title)}</span><small>${bili?'播放 '+e(r.observed_metrics.views_display)+' / 弹幕 '+e(r.observed_metrics.danmaku_display):e(r.observed_metrics.heat_display??r.observed_metrics.displayed_heat+' 热度')}</small></button>`).join('')}</div></details>`;}).join('');}
function render(){filtered=data.filter(applies);const nonBg=filtered.filter(r=>!r.excluded_from_metrics).length;document.getElementById('result-count').textContent=`初始样本：${nonBg} 条可见平台线索${filtered.length>nonBg?' + '+(filtered.length-nonBg)+' 条背景 / 待核验线索':''} / ${data.filter(r=>(isSummary||r.platform===platform)&&!r.excluded_from_metrics).length} 条已收录平台线索`;document.getElementById('content').innerHTML=temporalPanel()+officialPanel()+rolePanel()+(isSummary?summary():platformView());const query=new URLSearchParams();for(const [k,v]of Object.entries(state))if(v&&v!=='all')query.set(k,v);history.replaceState(null,'',location.pathname+(query.size?'?'+query:''));updateSelection();}
function updateSelection(){document.getElementById('selection-bar').hidden=!selected.size;document.getElementById('selected-count').textContent=`已选 ${selected.size} 条证据`;document.querySelectorAll('[data-select]').forEach(input=>input.checked=selected.has(input.dataset.select));}
function showDialog(id,html){let d=document.getElementById(id);d.innerHTML=`<div class="dialog-heading"><span>${id==='evidence'?'EVIDENCE / 证据档案':'SIDE BY SIDE / 并排比较'}</span><button class="close" data-close="${id}" aria-label="关闭">×</button></div>${html}`;d.showModal();}
function evidence(id){const r=data.find(r=>r.id===id);if(!r)return;let metrics=r.observed_metrics?Object.entries(r.observed_metrics).map(([k,v])=>`<div><dt>${e(metricLabel(k,r.platform))}</dt><dd>${e(Array.isArray(v)?v.join(' / '):typeof v==='object'?JSON.stringify(v):v)}</dd></div>`).join(''):'<div><dt>互动数据</dt><dd>未获取；不补零、不推算</dd></div>';let role=r.author_profile?.role||r.author_role||'未获取可核验的作者身份自述';showDialog('evidence',`<div class="dialog-body"><div class="record-badges">${tags(r)}<span class="badge">${e(r.id)}</span></div><h2>${e(r.title)}</h2><p class="lead">${e(r.claim)}</p><section><h3>可支持的观点</h3><p>${e(r.stance_summary||'未读取观点语料，仅记录榜单显示。')}</p></section><section><h3>发布者与身份依据</h3><p>${e(displayAuthor(r))}</p><p>${e(role)}</p>${r.author_profile?.basis?`<p class="fine">依据：${e(r.author_profile.basis)}</p>`:''}<p class="fine">只记录公开自述或机构角色，不据此推断受众属性。</p></section><dl class="evidence-facts"><div><dt>材料发布日期</dt><dd>${e(r.published_at||'未核验')}</dd></div><div><dt>原始公众号日期</dt><dd>${e(r.original_published_at||'未获取 / 不适用')}</dd></div><div><dt>事件日期</dt><dd>${e(r.event_dates||'未单独核验')}</dd></div><div><dt>采集时间</dt><dd>${e(r.captured_at)}</dd></div>${r.source_relationship?`<div><dt>转载关系</dt><dd>${e(r.source_relationship)}</dd></div>`:''}</dl><section><h3>来源的显示值</h3><p class="fine">保留原口径与时间。账号累计数据不是单帖互动；二手历史数值不是实时数值。</p><dl class="evidence-facts">${metrics}</dl></section>${r.detail_metrics?`<section><h3>视频详情页的另一次读取</h3><p class="fine">以下指标保留独立采集时间，不与榜单时刻合并；历史最高名次不是本次名次。</p><dl class="evidence-facts">${Object.entries(r.detail_metrics).map(([k,v])=>`<div><dt>${e(metricLabel(k,r.platform))}</dt><dd>${e(v)}</dd></div>`).join('')}</dl></section>`:''}${r.ai_disclosure?`<section><h3>页面的AI内容披露</h3><p>${e(r.ai_disclosure)}</p><p class="fine">披露不等于已核验素材授权或训练数据权利。</p></section>`:''}${r.original_access_note?`<section><h3>原文可访问性</h3><p>${e(r.original_access_note)}</p></section>`:''}<section class="limit-box"><h3>证据边界</h3><p>${e(Array.isArray(r.limitations)?r.limitations.join(' '):r.limitations)}</p>${r.id==='WD01'||r.id==='WD02'||r.id==='WD10'?'<p>6月28日已出现同题材视频。10月4日传播不能视为首次发言；完整访谈和原始事件时间仍待核验。</p>':''}</section><div class="dialog-links"><a class="primary-button" href="${e(sourceURL(r))}" target="_blank" rel="noopener noreferrer">打开已读取的来源 ↗</a>${r.original_url?`<a href="${e(r.original_url)}" target="_blank" rel="noopener noreferrer">原文入口（当前未读取）↗</a>`:''}${sourceURL(r)!==r.url?`<a href="${e(r.url)}" target="_blank" rel="noopener noreferrer">原帖链接（可能受限）↗</a>`:''}</div></div>`);}
function metricLabel(k,p){return ({views_display:p==='bilibili'?'播放量（非人数）':'浏览量（非人数）',danmaku_display:'弹幕（非评论）',metric_note:'指标口径',coins_display:'投币（显示值）',favorites_display:'收藏（显示值）',historical_best_rank_display:'历史最高名次（非本次）',published_at_display:'页面发布时间',captured_at:'详情采集时间',rank:'榜单名次',category_rank:'科技分类名次',displayed_heat:'页面相邻数值（口径待核）',rank_scope:'排名范围',heat_display:'平台热度（非人数）',measurement:'指标定义',likes_display:'赞（显示值）',comments_display:'评论（显示值）',provenance:'数字来源',measurement_time:'测量时间',note:'口径备注',video_views_display:'视频观看（显示值）',account_followers_display:'账号粉丝（非单帖）',account_total_likes_display:'账号累计获赞（非单帖）',unlabelled_post_values:'无标签数值（不赋予指标）',want_to_go:'想去（显示值）',discussion_count_display:'活动讨论（显示值）'})[k]||k;}
function compare(){const rs=data.filter(r=>selected.has(r.id));if(!rs.length)return;showDialog('compare',`<div class="dialog-body"><h2>${rs.length} 条证据，逐项对照</h2><p class="fine">手动选择不会自动建立同题关系。先核对具体命题、发布时间及转载链，再判断是否存在分歧。</p><div class="compare-grid">${rs.map(r=>`<section><div class="record-badges">${tags(r)}</div><h3>${e(r.topic)}</h3><strong>${e(r.id)} · ${e(displayAuthor(r))}</strong><h4>材料日期</h4><p>${e(r.published_at||'未核验')}</p><h4>具体表达</h4><p>${e(r.stance_summary||'未读取观点语料，仅记录榜单显示。')}</p><h4>局限</h4><p class="fine">${e(Array.isArray(r.limitations)?r.limitations.join(' '):r.limitations)}</p><a href="${e(sourceURL(r))}" target="_blank" rel="noopener noreferrer">来源 ↗</a></section>`).join('')}</div><button class="primary-button" data-export="selected">导出已选证据 JSON ↓</button></div>`);}
function method(){showDialog('evidence',`<div class="dialog-body"><p class="eyebrow">RESEARCH BOUNDARIES</p><h2>我们看到了什么，<br>又没看到什么。</h2><p class="lead">最近核查 ${e(checkedLabel())}；材料日期 ${e(contentRange())}。各平台及每条证据的实际采集时间分别保留，不代表同步更新。聚焦 AI，辅以实际取到的文化、假日与其他议题。数据不是全量，也不代表平台总体。</p><section><h3>01 / 四种证据，分开阅读</h3><p>官方榜单仅核验采集时刻的排名与平台热度，不证明标题事件本身。搜索索引仅证明搜索服务当时展示了该摘要。二手报道保留原帖链接与转载关系。直接原文包括已读取的X主帖及回复，也包括机构声明；X03 是2025年官网背景，不计为当前 X 帖子。</p></section><section><h3>02 / 不能得到的数字，不画图</h3><p>抖音官方榜最近保存于 ${e(checkedLabel(metadata.official_snapshots?.douyin?.captured_at))}，范围见榜单区；置顶内容不计入排名。微博科技分类榜最近保存于 ${e(checkedLabel(metadata.official_snapshots?.weibo?.captured_at))}，为有选择采样，分类名次不等于综合名次。微博话题点击会进入登录页，完整话题和评论未读取。B站综合榜最近保存于 ${e(checkedLabel(metadata.official_snapshots?.bilibili?.captured_at))}，名次综合内容质量与近期数据，并非按播放量直接排序；播放与弹幕各自记录，弹幕不是评论。另三个平台官方榜、统一时刻互动、代表性评论样本及受众画像尚未取得。页面覆盖图只展示收录条目数，不表示声量、流行程度、意见占比或用户结构。</p></section><section><h3>03 / 不同日期各司其职</h3><p>材料发布日期、事件日、采集时间分别记录。公众号日期通常属于转载页。李飞飞“两类劳动”的同题材6月已出现，10月是再次传播线索。缺失或矛盾日期保持可见。</p></section><section><h3>04 / 对照观点，不制造对立</h3><p>同题材料至少跨两个平台，才用作跨平台议题对照。不同关注重点不等于相反立场；转述同一原文不是独立验证。作者与受众严格分开，只记录公开自述角色。</p></section><section><h3>05 / 访问结果的边界</h3><p>B站、微博、抖音官方榜在普通公开页面可读，但不意味着完整评论都可读。X有直接原帖与少量回复，未取得官方趋势榜。微信公众号原文入口已核实，但当前访问受站点安全策略限制，因此保留署名转载等级。小红书已查笔记显示“暂时无法浏览”（300031）；这不能证明笔记被删除。读取方法失败，也不等于整个平台完全不可访问。</p></section><section><h3>06 / 初始样本与后续观察分开</h3><p>初始样本日期 ${e(metadata.snapshot_date)}，初始最近核查 ${e(checkedLabel(metadata.baseline_last_checked_at||metadata.last_checked_at))}；后续最新观察 ${e(checkedLabel(metadata.latest_observation_at||metadata.last_checked_at))}。初始记录与覆盖数不因后续榜单采样而增加。两时点比较仅连接同一条目与同口径指标；Top10区间新出现不是全平台新趋势，微博初始选样不能穷举新进入项。</p><p>浏览器观察时间不是服务器刷新时间，缓存新鲜度未知。取整显示值的差不是精确增长量。</p></section><section><h3>07 / 检索与导出范围</h3><p>筛选和导出均作用于当前页面的真实证据。JSON 保留完整口径，CSV 便于进一步研究。所有内容均为固定快照；无持续监控或自动刷新。</p></section></div>`);}
function csvCell(value){let text=String(Array.isArray(value)?value.join(' '):value&&typeof value==='object'?JSON.stringify(value):value??'');if(typeof value!=='number'&&/^[\s\p{Cc}\p{Cf}]*[=+\-@]/u.test(text))text="'"+text;return '"'+text.replace(/"/g,'""')+'"';}
function exportData(type){if(type==='temporal'){exportTemporal();return;}const rs=type==='selected'?data.filter(r=>selected.has(r.id)):filtered;let content,mime,ext;if(type==='csv'){let fields=['id','platform','topic','domain','published_at','captured_at','source_type','claim','stance_summary','observed_metrics','author_name','account_name','url','source_url','evidence_url','secondary_source_url','excluded_from_metrics','limitations'];content='\ufeff'+[fields.map(csvCell).join(','),...rs.map(r=>fields.map(k=>csvCell(r[k])).join(','))].join('\r\n');mime='text/csv;charset=utf-8';ext='csv';}else{content=JSON.stringify({snapshot:metadata.snapshot_date,initial_sample_last_checked_at:metadata.baseline_last_checked_at||metadata.last_checked_at,last_checked_at:metadata.last_checked_at,updated_date:metadata.updated_date||metadata.snapshot_date,known_content_date_range:metadata.known_content_date_range,scope:'公开样本及标明时间的官方榜单快照，非代表性调查',filters:state,records:rs},null,2);mime='application/json';ext='json';}let url=URL.createObjectURL(new Blob([content],{type:mime}));let a=document.createElement('a');a.href=url;a.download=`chengjing-initial-${metadata.snapshot_date||'undated'}-checked-${metadata.updated_date||metadata.snapshot_date}-${platform}-${rs.length}-records.${ext}`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify(`已导出 ${rs.length} 条证据`);}
function notify(s){const el=document.getElementById('toast');el.textContent=s;el.classList.add('visible');setTimeout(()=>el.classList.remove('visible'),2400);}
document.addEventListener('click',ev=>{const t=ev.target.closest('button,a');if(!t)return;if(t.dataset.evidence)evidence(t.dataset.evidence);if(t.dataset.temporal)temporalDetail(t.dataset.temporal);if(t.dataset.close)document.getElementById(t.dataset.close).close();if(t.dataset.export)exportData(t.dataset.export);if(t.dataset.group!==undefined){let g=groups[+t.dataset.group];(g.ids||g.evidence_ids||[]).filter(id=>filtered.some(r=>r.id===id)).forEach(id=>selected.add(id));updateSelection();compare();}switch(t.dataset.action){case'method':method();break;case'compare':compare();break;case'clear':selected.clear();updateSelection();break;case'reset':state={q:'',domain:'all',source:'all',time:'all'};document.getElementById('search').value='';for(let k of ['domain','source','time'])document.getElementById(k).value='all';render();break;}});
document.addEventListener('change',ev=>{let id=ev.target.dataset.select;if(id){if(ev.target.checked)selected.add(id);else selected.delete(id);updateSelection();}});
document.addEventListener('keydown',ev=>{if(ev.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)&&!document.querySelector('dialog[open]')){ev.preventDefault();document.getElementById('search').focus();}});
for(let d of document.querySelectorAll('dialog'))d.addEventListener('click',ev=>{if(ev.target===d){const r=d.getBoundingClientRect();if(ev.clientX<r.left||ev.clientX>r.right||ev.clientY<r.top||ev.clientY>r.bottom)d.close();}});
const fallbackGroups=[{title:'AI面试：初筛效率与沟通体验',kind:'同一场景 · 关注差异',summary:'微博作者谈拟人面试的不适、情绪劳动和初筛边界；公众号关联文章强调标准化效率与双向沟通。这里呈现互补关注，并非平台间阵营对立。',ids:['WD04','WD05','WD06','WX06']},{title:'AI输出：生成之后，谁来读懂？',kind:'同类问题 · 非相反立场',summary:'小红书标题指出阅读负担，公众号与 X 讨论约束写作和可视化。共同问题是输出可理解性；使用不同工具和任务，不能直接比较效果。',ids:['BX09','WX01','X08']},{title:'“两类劳动”：传播日期不是事件日期',kind:'同题材 · 历史对照',summary:'10月微博再传播与6月抖音视频出现类似主题。6月材料只能证明题材此前已出现，不能确定完整访谈的原始日期。',ids:['WD01','WD02','WD10'],caution:'历史标题采取反焦虑框架；当期作者自我定位不能代表劳动者总体。'}];
fetch('/data.json').then(r=>{if(!r.ok)throw Error('数据载入失败');return r.json();}).then(d=>{metadata=d.metadata||{snapshot_date:d.snapshot};temporal=d.temporal||{batches:[]};data=d.records;groups=Array.isArray(d.synthesis?.groups)?d.synthesis.groups.map(g=>({...g,kind:g.relation,summary:g.assessment,caution:(g.limitations||[]).join(' ')})):fallbackGroups;shell();render();}).catch(err=>{document.getElementById('app').innerHTML=`<main class="empty"><h1>证据暂时没有载入</h1><p>${e(err.message)}</p><button onclick="location.reload()">重试</button><a href="/">回到视图总览</a></main>`;});
